export function evaluate({ inputs, time }) {
  const g = 9.8;
  const u = inputs.launchSpeed;
  const T = 2 * u / g;
  const t = sdk.clamp(time, 0, T);
  const apexTime = u / g;
  const apexHeight = u * u / (2 * g);
  const v = u - g * t;
  const h = Math.max(0, u * t - g * t * t / 2);
  const top = Math.abs(t - apexTime) < 0.005;
  const vz = top ? 0 : v;
  const state = top ? 'Still for an instant' : (v > 0 ? 'Moving up' : 'Moving down');
  const yBase = 370, pxPer = 280 / 1.4;
  const y = yBase - h * pxPer;
  const x = 280;
  const objs = [];
  objs.push(sdk.line('guide.launch', 150, yBase + 14, 500, yBase + 14, { role: 'neutral' }));
  objs.push(sdk.text('guide.label', 150, yBase + 34, 'Launch height 0 m', { role: 'neutral' }));
  objs.push(sdk.circle('ball.toss', x, y, 28, { role: 'output' }));
  objs.push(...sdk.vector('vec.v', { x: x + 40, y: y }, { value: vz, direction: 'up' }, { scale: 14, minLength: 12, label: 'v', role: 'input' }));
  objs.push(...sdk.vector('vec.a', { x: x - 50, y: y }, { value: -g, direction: 'up' }, { scale: 5, minLength: 12, label: 'a', role: 'warning' }));
  objs.push(...sdk.callout(x + 110, y - 30, [state, 'Gravity pulls down'], { id: 'callout.toss' }));
  return {
    frame: { width: 640, height: 420, objects: objs, readouts: [{ id: 'motionState', value: state }, { id: 'gravityState', value: 'Gravity pulls down' }] },
    quantities: { launchSpeed: u, gravity: g, apexTime, apexHeight, velocity: vz, height: h, motionState: 0, gravityState: 0 }
  };
}
